import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static int[] p, sz;

    static int find(int x) {
        while (x != p[x]) x = p[x] = p[p[x]];
        return x;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        p = new int[n + 1];
        sz = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            p[i] = i;
            sz[i] = 1;
        }
        long ans = 0;
        for (int i = 0; i < q; i++) {
            String t = next();
            int x = find(nextInt()), y = find(nextInt());
            if (t.equals("F") && x != y) {
                if (sz[x] < sz[y]) {
                    int tmp = x;
                    x = y;
                    y = tmp;
                }
                p[y] = x;
                sz[x] += sz[y];
            } else if (t.equals("T")) {
                ans += sz[x] + sz[y];
            }
        }
        System.out.println(ans);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

var p, sz []int

func find(x int) int {
	for x != p[x] {
		p[x] = p[p[x]]
		x = p[x]
	}
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, q := nextInt(), nextInt()
	p = make([]int, n+1)
	sz = make([]int, n+1)
	for i := range p {
		p[i], sz[i] = i, 1
	}
	ans := 0
	for i := 0; i < q; i++ {
		t := string(token())
		x, y := find(nextInt()), find(nextInt())
		if t == "F" && x != y {
			if sz[x] < sz[y] {
				x, y = y, x
			}
			p[y] = x
			sz[x] += sz[y]
		} else if t == "T" {
			ans += sz[x] + sz[y]
		}
	}
	fmt.Println(ans)
}
